PLAN_BASE = 'אוספים נתונים בכל הדרכים שיש: הנקודה הנגררת בגרף, הטבלה והחישוב. מנסחים כלל מהנתונים, ובסוף מתנסים בו בשרטוט עם מחוונים.'
PLAN_FULL = 'מנחשים לפני שבודקים. אוספים נתונים בכל הדרכים שיש: הנקודה הנגררת בגרף, הטבלה והחישוב. מנסחים כלל מהנתונים, מנסים להפריך אותו בדוגמה נגדית, ובסוף מתנסים בו בשרטוט עם מחוונים.'
