def INV(title, goal, tool, plan, pilot=False):
    tool = list(tool) + [STAGE_A]
    return ('<span class="tag t-explain">חקירה</span> **%s**\n\n**מטרת החקירה.** %s\n\n**כלי הניסוי.**\n\n%s\n\n**מה עושים.** %s\n'
            % (title, goal, '\n'.join('- ' + t for t in tool), PLAN_FULL if pilot else PLAN_BASE))

