WHY15 = [r'בצד ימין $x>0$, ולכן $x^n>0$ לכל $n$, והסימן של $a$ קובע.', r'כש-$n$ זוגי, $x^n$ זהה ב-$x$ וב-$-x$.', r'כש-$n$ אי-זוגי, $x^n$ הפוך בסימן ב-$-x$, ולכן הקצוות הפוכים.']
i = nid()
c.add(ex(i, 'guided', r"""
**שלב א: איסוף נתונים.** בשרטוט הפונקציה $f(x)=a\cdot x^n$, **ו-$a$ ו-$n$ אינם נתונים**. הנקודה $P$ נגררת לאורך הגרף, ושיעוריה מוצגים לידה.

""" + _fig15(mystery={'a': -0.5, 'n': 3}, drags=[FREE('P', 0, min=-2.9, max=2.9)], xs=[-100, -10, 1, 10, 100]) + r"""
- א. מצאו את $f(2)$.
- ב. מצאו את $f(100)$.
- ג. מצאו את $n$.
- ד. מצאו את $f(-1000)$.
""", keys=['-4', '-500000', '3', '500000000'], hint_text=['איזה ערך מבקשים שאינו בטבלה ואינו בגרף?', r'ג: מ-$f(1)$ מוצאים את $a$, ואז פותרים $a\cdot2^n=-4$.', r'ד: הציבו $x=-1000$, $a=-0.5$ ו-$n=3$.'],
   answer=r"""
א. $-4$ ב. $-500{,}000$ ג. $3$ ד. $500{,}000{,}000$""", solution=steps([
    (r'א. $f(2)=-4$', r'קריאת שיעורי הנקודה $P$ ב-$x=2$'),
    (r'ב. $f(100)=-500{,}000$', r'קריאה מהטבלה ($x=100$ מחוץ לחלון הגרף)'),
    (r'ג. $f(1)=a=-0.5$ (מהטבלה), ו-$-0.5\cdot2^n=-4\Rightarrow2^n=8\Rightarrow n=3$', r'הצבת טענה א, והערך $f(1)$ מהטבלה'),
    (r'ד. $f(-1000)=-0.5\cdot(-1000)^3=500{,}000{,}000$', r'הצבת $x=-1000$, $a=-0.5$ ו-$n=3$')])))
