c.text(r"""
<span class="tag t-explain">חקירה ב.</span> **ומה עם פולינום שלם?** בשרטוט $f(x)=x^3-12x$ (כחול) לעומת האיבר המוביל $y=x^3$ (מקווקו), אבל **בסקאלה מכווצת**: כל גרף מתואר מרחוק, כאילו $x$ מוגדל פי $Z$. הגדילו את $Z$ ושימו לב: מה קורה לשני הגרפים? והטבלה מראה את הערכים האמיתיים.
""")
c.add(FG([-3, 3], [-10, 10], [{'f': '(pow(Z*x,3)-12*Z*x)/pow(Z,3)', 'cls': 0, 'name': 'f', 'nx': 1.5, 'dx': 14, 'dy': -4}, {'f': 'pow(x,3)', 'cls': 1, 'dash': True, 'name': 'x³', 'nx': -2.0, 'dx': -14, 'dy': 4},
    {'f': 'pow(x,3)-12*x', 'hide': True}, {'f': 'pow(x,3)', 'hide': True}],
    params=PAR(Z=(1, 30, 1, 1, 'Z')), ystep=2,
    readout=[{'k': 'tpl', 'pre': 'מכווצים את הגרף פי', 'tpl': '{Z}'},
             {'k': 'tbl', 'xs': [-100, -10, 10, 100], 'rows': [{'i': 2, 'name': 'f(x)'}, {'i': 3, 'name': 'x^3'}]}],
    alt='גרף פולינום מכווץ מול האיבר המוביל', caption=r'ככל ש-$Z$ גדול יותר, הגרף הכחול מתקרב לגרף המקווקו: בקצוות הפולינום מתנהג כמו האיבר המוביל.'))
c.text(r"""
**כלל.** הפולינום $f(x)=a_nx^n+\dots+a_1x+a_0$ מתנהג בקצוות כמו **האיבר המוביל** $a_nx^n$, כי כש-$|x|$ גדול, החזקה הגדולה ביותר "גוברת" על כל האחרות. לכן ההתנהגות בקצוות תלויה רק בשני דברים: **זוגיות $n$** ו**סימן $a_n$**:

| | $a_n>0$ | $a_n<0$ |
|:--|:--|:--|
| **$n$ זוגי** | $x\to\infty$: $f\to+\infty$ ; $x\to-\infty$: $f\to+\infty$ (שני הקצוות למעלה) | $x\to\infty$: $f\to-\infty$ ; $x\to-\infty$: $f\to-\infty$ (שני הקצוות למטה) |
| **$n$ אי-זוגי** | $x\to\infty$: $f\to+\infty$ ; $x\to-\infty$: $f\to-\infty$ (ימין למעלה, שמאל למטה) | $x\to\infty$: $f\to-\infty$ ; $x\to-\infty$: $f\to+\infty$ (ימין למטה, שמאל למעלה) |

**חשוב:** ההתנהגות בקצוות לא אומרת כמה אפסים או קיצונים יש לפולינום. היא עוזרת **לקבוע את הסימן** בקצוות, **להתאים גרף למשוואה** ולשרטט.
""")

c.add(SUMBOX(r"""
**סיכום החקירה.** פולינום $f(x)=a_nx^n+\dots+a_0$ מתנהג בקצוות כמו **האיבר המוביל** $a_nx^n$. ההתנהגות תלויה רק בזוגיות $n$ ובסימן $a_n$:

| | $a_n>0$ | $a_n<0$ |
|:--|:--|:--|
| $n$ זוגי | שני הקצוות למעלה | שני הקצוות למטה |
| $n$ אי-זוגי | ימין למעלה, שמאל למטה | ימין למטה, שמאל למעלה |

**נימוק:** כש-$|x|$ גדול, החזקה הגדולה ביותר "גוברת" על כל החזקות האחרות.
"""))
i = nid()
c.add(ex(i, 'guided', r"""
**התנסות מיידית.** קבעו $a$ ו-$n$ כך שכש-$x\to\infty$ מתקיים $f\to-\infty$ וכש-$x\to-\infty$ מתקיים $f\to+\infty$, ולחצו "בדיקה".

""" + _fig15(goal={'expr': 'a<0 && rem(n,2)==1'}, goalHint='הקצוות הפוכים, ולכן n אי-זוגי. הקצה הימני למטה, ולכן a שלילי.') + r"""
""", act=True, answer=r'$a<0$ ו-$n$ אי-זוגי, למשל $a=-1$, $n=3$', solution=steps([
    (r'קצוות בכיוונים הפוכים', r'$n$ אי-זוגי'),
    (r'הקצה הימני למטה', r'$a<0$')])))
at(i, params={'a': -1, 'n': 3})

c.add(ex(nid(), 'example', r"""
נתונה $f(x)=-2x^5+3x^3-x$.

א. האיבר המוביל: $-2x^5$ (המעריך הגדול ביותר). המעריך אי-זוגי והמקדם שלילי.

ב. לכן כש-$x\to\infty$: $f\to-\infty$, וכש-$x\to-\infty$: $f\to+\infty$ (ימין למטה, שמאל למעלה).

ג. בדיקה במספרים: $f(100)=-2\cdot10^{10}+3\cdot10^6-100=-19{,}997{,}000{,}100$ (שלילי וגדול מאוד), ו-$f(-100)=+19{,}997{,}000{,}100$. האיבר $-2\cdot10^{10}$ קובע כמעט הכול.
"""))
assert -2*100**5+3*100**3-100 == -19997000100 and -2*(-100)**5+3*(-100)**3+100 == 19997000100
