c.add(ex(i, 'solo', r"""
לכל פולינום בחרו את ההתנהגות בקצוות.
""", mc=[
    dict(label='א', q=r'$f(x)=2x^4-3x$', opts=['שני הקצוות למעלה', 'שני הקצוות למטה', 'ימין למעלה ושמאל למטה', 'ימין למטה ושמאל למעלה'], c=0, why=r'האיבר המוביל $2x^4$: מעריך זוגי ומקדם חיובי.'),
    dict(label='ב', q=r'$g(x)=6x^3-x$', opts=['שני הקצוות למעלה', 'שני הקצוות למטה', 'ימין למעלה ושמאל למטה', 'ימין למטה ושמאל למעלה'], c=2, why=r'האיבר המוביל $6x^3$: מעריך אי-זוגי ומקדם חיובי.'),
    dict(label='ג', q=r'$h(x)=-x^6+6x^2-1$', opts=['שני הקצוות למעלה', 'שני הקצוות למטה', 'ימין למעלה ושמאל למטה', 'ימין למטה ושמאל למעלה'], c=1, why=r'האיבר המוביל $-x^6$: מעריך זוגי ומקדם שלילי.'),
    dict(label='ד', q=r'$k(x)=-0.5x^5+x^3-1$', opts=['שני הקצוות למעלה', 'שני הקצוות למטה', 'ימין למעלה ושמאל למטה', 'ימין למטה ושמאל למעלה'], c=3, why=r'האיבר המוביל $-0.5x^5$: מעריך אי-זוגי ומקדם שלילי.')],
   answer=r'א. שני הקצוות למעלה ב. ימין למעלה ושמאל למטה ג. שני הקצוות למטה ד. ימין למטה ושמאל למעלה'))
